{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2156-05-17 18:00:00",
      "speaker": "Doctor",
      "text": "Hello, I’m Dr. Lee. I’ve reviewed your chart and wanted to talk about why you came in today."
    },
    {
      "turn_number": 2,
      "time": "2156-05-17 18:02:00",
      "speaker": "Patient",
      "text": "Hi, yes. I’ve had this cough and low fevers for about a week now. Started with a sore throat and congestion."
    },
    {
      "turn_number": 3,
      "time": "2156-05-17 18:04:00",
      "speaker": "Doctor",
      "text": "I see. And your husband was sick recently too?"
    },
    {
      "turn_number": 4,
      "time": "2156-05-17 18:05:00",
      "speaker": "Patient",
      "text": "Yes, he had flu-like symptoms. I thought I’d get better, but the cough just stuck around."
    },
    {
      "turn_number": 5,
      "time": "2156-05-17 18:06:00",
      "speaker": "Doctor",
      "text": "Makes sense. We tested you in the ER and found you have RSV — that’s a respiratory virus, common in adults but can be more serious in people with weakened immunity."
    },
    {
      "turn_number": 6,
      "time": "2156-05-17 18:08:00",
      "speaker": "Patient",
      "text": "Oh, okay. Is that dangerous for me?"
    },
    {
      "turn_number": 7,
      "time": "2156-05-17 18:10:00",
      "speaker": "Doctor",
      "text": "Because of your history — the stem cell transplant and ongoing immune suppression — we take it seriously. But you’re not having trouble breathing, and your oxygen level is good."
    },
    {
      "turn_number": 8,
      "time": "2156-05-17 18:12:00",
      "speaker": "Patient",
      "text": "That’s a relief. I did notice some wheezing at home."
    },
    {
      "turn_number": 9,
      "time": "2156-05-17 18:13:00",
      "speaker": "Doctor",
      "text": "Yes, we heard that. We gave you an albuterol treatment, and your lungs are sounding much clearer now."
    },
    {
      "turn_number": 10,
      "time": "2156-05-17 18:15:00",
      "speaker": "Patient",
      "text": "Good. I use my inhaler at home sometimes, especially when I feel tight."
    },
    {
      "turn_number": 11,
      "time": "2156-05-17 18:16:00",
      "speaker": "Doctor",
      "text": "We’ll keep that available for you here and send it home with instructions to use as needed."
    },
    {
      "turn_number": 12,
      "time": "2156-05-17 18:18:00",
      "speaker": "Doctor",
      "text": "We also did a chest X-ray to make sure there’s no pneumonia. Good news — your lungs look clear."
    },
    {
      "turn_number": 13,
      "time": "2156-05-17 18:20:00",
      "speaker": "Patient",
      "text": "That’s good. I was worried about that."
    },
    {
      "turn_number": 14,
      "time": "2156-05-17 18:21:00",
      "speaker": "Doctor",
      "text": "We also checked your flu swab — it was negative — and no bacteria in blood or urine. So RSV is the main issue."
    },
    {
      "turn_number": 15,
      "time": "2156-05-17 18:23:00",
      "speaker": "Patient",
      "text": "And my immune system? I get IVIG every week."
    },
    {
      "turn_number": 16,
      "time": "2156-05-17 18:25:00",
      "speaker": "Doctor",
      "text": "Exactly. We’re going to give you your scheduled IVIG infusion tomorrow. It’ll help support your immunity while you fight this virus."
    },
    {
      "turn_number": 17,
      "time": "2156-05-17 18:27:00",
      "speaker": "Patient",
      "text": "Okay, that makes me feel better. What about my other meds?"
    },
    {
      "turn_number": 18,
      "time": "2156-05-17 18:28:00",
      "speaker": "Doctor",
      "text": "We’re continuing your regular medications — prednisone for GVHD, antivirals, antifungals, and your blood thinner."
    },
    {
      "turn_number": 19,
      "time": "2156-05-17 18:30:00",
      "speaker": "Doctor",
      "text": "One change — we lowered your long-acting morphine dose. It can slow stomach emptying, which might worsen bloating or diarrhea."
    },
    {
      "turn_number": 20,
      "time": "2156-05-17 18:32:00",
      "speaker": "Patient",
      "text": "Oh, right. I’ve had that problem before. I’ve been using loperamide and stool softeners."
    },
    {
      "turn_number": 21,
      "time": "2156-05-17 18:34:00",
      "speaker": "Doctor",
      "text": "Yes, and you’re reporting regular bowel movements now, which is great. We’ll keep those on board as needed."
    },
    {
      "turn_number": 22,
      "time": "2156-05-17 18:36:00",
      "speaker": "Patient",
      "text": "My back’s been a little stiff, but not worse than usual."
    },
    {
      "turn_number": 23,
      "time": "2156-05-17 18:38:00",
      "speaker": "Doctor",
      "text": "We see you have osteoporosis and old compression fractures. You’re on baclofen and vitamin D — we’ll keep that up."
    },
    {
      "turn_number": 24,
      "time": "2156-05-17 18:40:00",
      "speaker": "Patient",
      "text": "And my liver enzymes — they’ve been a bit high before."
    },
    {
      "turn_number": 25,
      "time": "2156-05-17 18:42:00",
      "speaker": "Doctor",
      "text": "Yes, your liver tests are mildly elevated, which we expect with chronic GVHD. But your recent biopsy didn’t show active GVH in the liver."
    },
    {
      "turn_number": 26,
      "time": "2156-05-17 18:44:00",
      "speaker": "Patient",
      "text": "So we’re not changing anything there?"
    },
    {
      "turn_number": 27,
      "time": "2156-05-17 18:45:00",
      "speaker": "Doctor",
      "text": "No, we’ll keep your prednisone at 7.5 mg daily and continue the eye drops for dry eyes."
    },
    {
      "turn_number": 28,
      "time": "2156-05-18 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. How are you feeling today?"
    },
    {
      "turn_number": 29,
      "time": "2156-05-18 09:02:00",
      "speaker": "Patient",
      "text": "Morning. My cough is a bit better, and I haven’t wheezed since yesterday’s treatment."
    },
    {
      "turn_number": 30,
      "time": "2156-05-18 09:04:00",
      "speaker": "Doctor",
      "text": "That’s great. We’re going to give your IVIG infusion later this morning — same dose you get weekly."
    },
    {
      "turn_number": 31,
      "time": "2156-05-18 09:06:00",
      "speaker": "Patient",
      "text": "Okay. Any other blood tests today?"
    },
    {
      "turn_number": 32,
      "time": "2156-05-18 09:08:00",
      "speaker": "Doctor",
      "text": "We checked your labs this morning. White count went up a bit, which is expected with infection. Liver enzymes are stable."
    },
    {
      "turn_number": 33,
      "time": "2156-05-18 09:10:00",
      "speaker": "Patient",
      "text": "And my kidney function? Glucose was high last time."
    },
    {
      "turn_number": 34,
      "time": "2156-05-18 09:12:00",
      "speaker": "Doctor",
      "text": "Your kidney function is fine. Glucose was a bit high, but likely from the stress of illness. We didn’t see signs of diabetes."
    },
    {
      "turn_number": 35,
      "time": "2156-05-18 13:00:00",
      "speaker": "Doctor",
      "text": "Hi again. You got your IVIG a little while ago. How are you feeling?"
    },
    {
      "turn_number": 36,
      "time": "2156-05-18 13:02:00",
      "speaker": "Patient",
      "text": "I’m okay. A little tired, but no headache or reaction."
    },
    {
      "turn_number": 37,
      "time": "2156-05-18 13:04:00",
      "speaker": "Doctor",
      "text": "Good. That means it went smoothly. We’re planning to discharge you tomorrow morning if you keep improving."
    },
    {
      "turn_number": 38,
      "time": "2156-05-18 13:06:00",
      "speaker": "Patient",
      "text": "Great. Any follow-up I should know about?"
    },
    {
      "turn_number": 39,
      "time": "2156-05-18 13:08:00",
      "speaker": "Doctor",
      "text": "Yes — plan to see your hematologist in two weeks. And your next IVIG is in about a month, unless you have issues before then."
    },
    {
      "turn_number": 40,
      "time": "2156-05-19 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’re looking well. We’re going to discharge you today."
    },
    {
      "turn_number": 41,
      "time": "2156-05-19 09:02:00",
      "speaker": "Patient",
      "text": "That’s great to hear. Is everything in order?"
    },
    {
      "turn_number": 42,
      "time": "2156-05-19 09:04:00",
      "speaker": "Doctor",
      "text": "Yes. Your cough is much better, lungs are clear, and you’re back to your baseline. We’ll send you home with instructions and a full med list."
    },
    {
      "turn_number": 43,
      "time": "2156-05-19 09:06:00",
      "speaker": "Patient",
      "text": "Should I watch for anything?"
    },
    {
      "turn_number": 44,
      "time": "2156-05-19 09:08:00",
      "speaker": "Doctor",
      "text": "Call if you develop fever, shortness of breath, or worsening cough. Otherwise, keep using your albuterol if you wheeze."
    },
    {
      "turn_number": 45,
      "time": "2156-05-19 09:10:00",
      "speaker": "Patient",
      "text": "And my other symptoms — joint pain, stomach — should stay the same?"
    },
    {
      "turn_number": 46,
      "time": "2156-05-19 09:12:00",
      "speaker": "Doctor",
      "text": "Yes, those are managed as before. Continue your GVHD and pain meds, and the lovenox for blood clot prevention."
    },
    {
      "turn_number": 47,
      "time": "2156-05-19 09:14:00",
      "speaker": "Patient",
      "text": "Thank you. I feel much better than when I came in."
    },
    {
      "turn_number": 48,
      "time": "2156-05-19 09:16:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care, and don’t hesitate to call if anything comes up."
    },
    {
      "turn_number": 49,
      "time": "2156-05-19 09:18:00",
      "speaker": "Patient",
      "text": "I will. Have a good day."
    },
    {
      "turn_number": 50,
      "time": "2156-05-19 09:20:00",
      "speaker": "Doctor",
      "text": "You too. The nurse will go over discharge papers shortly."
    }
  ],
  "summary": {
    "admission_start": "2156-05-17 17:38:00",
    "admission_end": "2156-05-19 17:00:00",
    "summary_paragraph": "The patient was admitted with a persistent cough and low-grade fevers after a week of progressive respiratory symptoms, including fatigue, sore throat, and nasal congestion. She tested positive for RSV, with a negative flu swab and no evidence of bacterial infection or pneumonia on chest X-ray. She received supportive care, including albuterol treatments for wheezing and her scheduled IVIG infusion to support immune function. Her symptoms improved significantly during the hospital stay. Chronic conditions, including chronic graft-versus-host disease, hypogammaglobulinemia, and osteoporosis, were monitored and managed without major changes. The long-acting morphine dose was reduced to mitigate delayed gastric emptying. She remained stable, was discharged home in improved condition, and advised to follow up with hematology in two weeks.",
    "problems": [
      "Respiratory syncytial virus (RSV)",
      "Chronic graft-versus-host disease",
      "Other selective immunoglobulin deficiencies",
      "Chronic myeloid leukemia, in remission",
      "Osteoporosis, unspecified",
      "Diarrhea",
      "Abdominal pain, unspecified site",
      "Pain in joint, multiple sites",
      "Other chronic pain",
      "Personal history of venous thrombosis and embolism",
      "Displacement of thoracic intervertebral disc without myelopathy"
    ]
  }
}
